await page.goto('https://creativecommons.org/licenses/by/4.0/');
await page.evaluate(() => { const links = [...document.querySelectorAll('a')]; const link = links.find(a => /human readable|deed|plain language/i.test(a.innerText)); if (link) location.href = link.href; });
await page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.match(/Creative Commons Attribution 4\.0 International Public License/i)?.[0] || document.querySelector('h1')?.innerText || '', values: [], answer: location.href}));

await page.goto('https://www.rfc-editor.org/info/rfc8259');
await page.evaluate(() => { const text = document.body.innerText; const lines = text.split('
').map(x=>x.trim()).filter(Boolean); const status = lines.find(x => /^Status\s*$/i.test(x)); const idx = status ? lines.indexOf(status) : -1; const value = idx >= 0 ? lines[idx+1] : (text.match(/Status\s*
\s*([^
]+)/i)||[])[1]; return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: 'Status', values: [value], answer: value}); });

await page.goto('https://practice.expandtesting.com/form-validation');
await page.getByLabel('Contact name').fill('Alex Example');
await page.getByLabel('Contact number').fill('012-3456789');
await page.getByLabel('Date').fill('15/01/2030');
await page.getByLabel('Payment method').selectOption({label:'Card'});
await page.getByRole('button', {name:'Submit'}).click();
page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText, values: [], answer: document.body.innerText.match(/[^.!?]*thank[^.!?]*[.!?]/i)?.[0]?.trim() || ''}))

await page.goto('https://practice.expandtesting.com/form-validation');
await page.evaluate(() => { const fields = [...document.querySelectorAll('input, select, textarea')]; for (const el of fields) { const label = (el.labels?.[0]?.innerText || el.getAttribute('aria-label') || el.name || el.id || '').toLowerCase(); if (label.includes('contact name')) el.value = 'Alex Example'; else if (label.includes('contact number')) el.value = '012-3456789'; else if (label.includes('date') || label.includes('pick up')) el.value = el.type === 'date' ? '2030-01-15' : '15/01/2030'; else if (el.tagName === 'SELECT') { const option = [...el.options].find(o => /card/i.test(o.text)); if (option) el.value = option.value; } el.dispatchEvent(new Event('input', {bubbles:true})); el.dispatchEvent(new Event('change', {bubbles:true})); } });
await page.getByRole('button', {name:'Submit'}).click();
page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText, values: ['Alex Example', '012-3456789', '15 January 2030', 'Card'], answer: document.body.innerText.match(/[^.!?]*thank[^.!?]*[.!?]/i)?.[0]?.trim() || ''}))
